 static void PutStaticString(byte[] b,int at,long block,string text){if(text.Length>350)throw new IOException("SVG路径长度超限。");BitConverter.GetBytes(block+at+8).CopyTo(b,at);BitConverter.GetBytes(-1).CopyTo(b,at+8);BitConverter.GetBytes(text.Length).CopyTo(b,at+12);BitConverter.GetBytes((long)24).CopyTo(b,at+24);Encoding.Unicode.GetBytes(text+"\0").CopyTo(b,at+32);}
